-- ============================================================
-- SEED: Módulo 24 — Discourse Markers (C2)
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'discourse-markers';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo discourse-markers não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 1: Spoken Discourse Markers (well, you know, I mean, actually)
  (cid,1,1,'multiple_choice','In the sentence "Well, I think the results were somewhat unexpected," what function does "well" serve?','signals hesitation or a shift in the speaker''s thinking before making a point','["signals strong agreement","signals hesitation or a shift in the speaker''s thinking before making a point","introduces a formal argument","signals the end of a topic"]','"Well" in spoken discourse is a floor-managing device that signals a pause, hesitation, or reorientation before a point.','medium'),
  (cid,1,2,'gap_fill','A: "Did you enjoy the lecture?" B: "_____, it was interesting, but a bit long." (hesitation/softening before an honest opinion)','Well',NULL,'"Well" at the start of a response signals that the speaker is considering their answer or softening a critical point.','easy'),
  (cid,1,3,'multiple_choice','In "The project was, you know, kind of complicated," what does "you know" signal?','an appeal to shared knowledge or a request for the listener''s understanding','["formal academic hedging","an appeal to shared knowledge or a request for the listener''s understanding","strong certainty about a claim","a transition to a new topic"]','"You know" is an informal discourse marker that invites shared understanding or solidarity. Common in casual speech.','medium'),
  (cid,1,4,'gap_fill','A: "How was the exam?" B: "_____ (I mean), I thought it was difficult, but I think I passed."','I mean',NULL,'"I mean" is used to clarify, self-correct, or reformulate a point. Extremely common in informal spoken English.','easy'),
  (cid,1,5,'multiple_choice','In "I actually enjoyed the lecture more than I expected," what function does "actually" serve?','signals something that is contrary to expectation or a previous assumption','["signals a correction of misinformation","signals something that is contrary to expectation or a previous assumption","marks the end of a narrative","indicates the most important point"]','"Actually" signals a contrast between what was expected and what happened. It can also politely contradict.','medium'),
  (cid,1,6,'gap_fill','A: "You don''t like jazz, do you?" B: "_____ (actually), I love it — I play saxophone in a band."','Actually',NULL,'"Actually" introduces a polite but direct contradiction of the previous speaker''s assumption.','easy'),
  (cid,1,7,'multiple_choice','In spoken discourse, "right?" at the end of a sentence (as in "It was a great presentation, right?") functions as:','a tag or check question inviting agreement or confirmation from the listener','["a formal rhetorical question","a tag or check question inviting agreement or confirmation from the listener","a strong assertion","a way to close a conversation"]','"Right?" as a spoken discourse marker functions as an informal tag question seeking listener agreement.','medium'),
  (cid,1,8,'gap_fill','A: "So the meeting was at 3pm, and then, _____ (anyway), we decided to reschedule it."','anyway',NULL,'"Anyway" signals a return to the main point after a digression, or a change of topic. Common in casual conversation.','easy'),

  -- BLOCK 2: More Spoken Markers (as I was saying, right, anyway)
  (cid,2,9,'multiple_choice','In "As I was saying, the most important factor is reproducibility," what does "as I was saying" signal?','a return to a previous point that was interrupted or digressed from','["the introduction of a new argument","a return to a previous point that was interrupted or digressed from","a summary of the entire discussion","an expression of uncertainty"]','"As I was saying" is a discourse marker that resumes a thread of conversation that was interrupted.','medium'),
  (cid,2,10,'gap_fill','"We started discussing the results — _____ (as I was saying) — they were far more significant than expected."','as I was saying',NULL,'"As I was saying" marks a return to the main thread after an interruption or side comment.','easy'),
  (cid,2,11,'multiple_choice','Which spoken discourse marker typically signals that a speaker is about to close a topic or conversation?','anyway','["well","actually","I mean","anyway"]','"Anyway" can signal topic closure ("Let''s move on") or a return to the main point. Often used to wrap up a digression.','medium'),
  (cid,2,12,'gap_fill','"I''m not sure exactly when it happened — _____ (you know), it was a long time ago."','you know',NULL,'"You know" is used when the speaker is struggling to be precise and invites the listener''s understanding and patience.','easy'),
  (cid,2,13,'multiple_choice','"I mean, it''s not that I disagree with the professor — it''s just that the evidence seems inconclusive." What is the function of "I mean"?','to clarify or qualify the speaker''s previous statement','["to introduce a formal argument","to clarify or qualify the speaker''s previous statement","to end the conversation","to strongly agree with someone"]','"I mean" reformulates or clarifies what was just said, preventing misunderstanding.','medium'),
  (cid,2,14,'gap_fill','"Well, it''s a complex issue. _____ (right), the point is that both sides have valid arguments."','Right',NULL,'"Right" as a discourse marker can signal an acknowledgment of complexity before advancing a key point.','medium'),
  (cid,2,15,'multiple_choice','How do spoken discourse markers differ from academic connectors?','Spoken markers manage interaction, signal attitude, and organize talk; academic connectors signal logical relationships between propositions.','["They have the same function.","Spoken markers manage interaction, signal attitude, and organize talk; academic connectors signal logical relationships between propositions.","Spoken markers are more precise than academic connectors.","Academic connectors are always shorter than spoken markers."]','Spoken discourse markers are interactional and manage conversation; academic connectors are propositional and organize text logic.','hard'),
  (cid,2,16,'gap_fill','A: "Are you coming to the seminar?" B: "_____ (well), I''m not sure — it depends on whether my experiment finishes in time."','Well',NULL,'"Well" signals a delayed, uncertain response — the speaker is thinking through the answer before committing.','easy'),

  -- BLOCK 3: Written Academic Discourse – "With regard to" / "In terms of"
  (cid,3,17,'gap_fill','_____ (with regard to) the second hypothesis, the results provide only partial support.','With regard to',NULL,'"With regard to" = a formal frame marker introducing a new topic or aspect. Common in academic and formal writing.','medium'),
  (cid,3,18,'multiple_choice','_____ the environmental impact, the proposed dam would affect an area of approximately 500 square kilometers.','In terms of','["Talking about","In terms of","With regard to speaking","Regarding to"]','"In terms of" introduces a specific dimension or angle of analysis. → In terms of the environmental impact.','medium'),
  (cid,3,19,'gap_fill','_____ (as far as) methodology is concerned, the study employed a randomized controlled trial design.','As far as',NULL,'"As far as X is concerned" is a formal frame marker. → As far as methodology is concerned.','medium'),
  (cid,3,20,'multiple_choice','_____ the economic implications are concerned, the policy shift would require significant structural adjustment.','As far as','["In terms about","Regarding about","As far as","With about"]','"As far as X is concerned" correctly frames the topic. → As far as the economic implications are concerned.','medium'),
  (cid,3,21,'gap_fill','_____ (with respect to) the study''s limitations, the authors acknowledge that the sample was not nationally representative.','With respect to',NULL,'"With respect to" is a formal academic frame marker. → With respect to the study''s limitations.','medium'),
  (cid,3,22,'multiple_choice','Which phrase most naturally introduces a specific topic in an academic paragraph?','Turning to the question of carbon capture technology...','["About carbon capture technology...","Turning to the question of carbon capture technology...","Speaking of carbon capture technology...","What about carbon capture technology..."]','"Turning to" is a formal written discourse marker that shifts focus to a new aspect or question.','medium'),
  (cid,3,23,'gap_fill','_____ (turning to) the issue of data interpretation, it should be noted that multiple frameworks have been applied.','Turning to',NULL,'"Turning to" signals a deliberate shift to a new sub-topic within an academic text.','medium'),
  (cid,3,24,'multiple_choice','In academic writing, "with regard to" and "with respect to" differ from "as far as X is concerned" in that:','they are directly followed by a noun phrase, while "as far as X is concerned" embeds the topic within a clause','["they are more informal","they are directly followed by a noun phrase, while \"as far as X is concerned\" embeds the topic within a clause","they always appear at the end of sentences","they are used only in scientific writing"]','"With regard to/respect to + noun phrase" vs "As far as + noun phrase + is concerned" — structural difference.','hard'),

  -- BLOCK 4: Written Academic Markers – "It should be noted" / "It is worth noting"
  (cid,4,25,'gap_fill','_____ (it should be noted) that the study was conducted during an atypical period, which may have affected the results.','It should be noted',NULL,'"It should be noted that" is a stance marker drawing the reader''s attention to an important caveat or qualification.','medium'),
  (cid,4,26,'multiple_choice','_____ that the participants were self-selected, which may introduce selection bias into the findings.','It is worth noting','["It should note","It is worth noting","It notes","Worth noting that"]','"It is worth noting that" introduces a relevant but secondary observation that the reader should keep in mind.','medium'),
  (cid,4,27,'gap_fill','_____ (it is important to note) that correlation does not imply causation in this context.','It is important to note',NULL,'"It is important to note that" is a stance marker used to emphasize a critical methodological or interpretive caveat.','medium'),
  (cid,4,28,'multiple_choice','Which sentence uses a written academic discourse marker correctly?','It should be noted that the data were collected before the policy change took effect.','["It should note that the data were collected before the policy change.","It is noting that the data were collected before the policy change.","It should be noted that the data were collected before the policy change took effect.","Worth noting the data were collected before the policy change."]','"It should be noted that + clause" is the correct structure. → It should be noted that the data were collected.','medium'),
  (cid,4,29,'gap_fill','_____ (it is worth pointing out) that this finding contradicts several previous studies on the same topic.','It is worth pointing out',NULL,'"It is worth pointing out that" draws attention to a noteworthy or unexpected finding.','medium'),
  (cid,4,30,'multiple_choice','What is the function of "It should be noted that" in academic writing?','to introduce an important qualification, caveat, or supplementary point that the reader should keep in mind','["to make a strong assertion","to begin a conclusion","to introduce an important qualification, caveat, or supplementary point","to introduce an example"]','"It should be noted that" signals that the following information is relevant and should not be overlooked.','medium'),
  (cid,4,31,'gap_fill','_____ (it is also relevant to mention) that the researchers had access to a longitudinal dataset spanning 20 years.','It is also relevant to mention',NULL,'"It is also relevant to mention that" introduces additional pertinent information within an academic argument.','medium'),
  (cid,4,32,'multiple_choice','How does "it is worth noting" differ from "it should be noted" in academic register?','They are nearly synonymous; "it is worth noting" can sound slightly less formal, while "it should be noted" is standard in most academic genres.','["\"It is worth noting\" is more formal.","\"It should be noted\" is used only in conclusions.","They are nearly synonymous; \"it is worth noting\" can sound slightly less formal, while \"it should be noted\" is standard in most academic genres.","\"It is worth noting\" requires a question mark."]','Both are stance markers; the difference is minimal, though "it should be noted" is perhaps slightly more authoritative.','hard'),

  -- BLOCK 5: TOEFL Academic – Text Organization Markers
  (cid,5,33,'gap_fill','[TOEFL Reading] _____ (in the first place), the study identifies a significant gap in existing research on urban heat islands.','In the first place',NULL,'"In the first place" = text organization marker introducing the first main point. More formal than "firstly."','medium'),
  (cid,5,34,'multiple_choice','[TOEFL Reading] "Turning now to the second issue raised in the reading, the lecture challenges the claim that..."  What does "Turning now to" signal?','a deliberate, organized shift to the next point in the argument','["a conclusion","a summary","a deliberate, organized shift to the next point in the argument","an example"]','"Turning now to" is a macrostructure marker that organizes the text by signaling a shift between sections.','medium'),
  (cid,5,35,'gap_fill','[TOEFL Listening] _____ (with reference to) the lecture''s main claim, the professor argues that urban agriculture cannot scale effectively without infrastructure investment.','With reference to',NULL,'"With reference to" frames the content that follows by identifying the specific topic being addressed.','medium'),
  (cid,5,36,'multiple_choice','[TOEFL Reading] "On the subject of biodiversity loss, the author makes three key claims." What is the function of "on the subject of"?','to introduce and frame the specific topic being addressed','["to conclude the discussion","to introduce and frame the specific topic being addressed","to express the author''s opinion","to introduce a contrast"]','"On the subject of" is a formal frame marker that introduces the specific issue to be discussed.','medium'),
  (cid,5,37,'gap_fill','[TOEFL Listening] The professor used the phrase "_____ (turning to) the economic dimension of this problem" to shift from discussing environmental to economic impacts.','Turning to',NULL,'"Turning to" signals an organized transition between aspects of an academic argument or lecture.','easy'),
  (cid,5,38,'multiple_choice','[TOEFL Reading] "In terms of methodology, the study diverges significantly from previous research in this area." What is the function of "In terms of methodology"?','to frame the dimension of analysis that will follow','["to criticize the methodology","to frame the dimension of analysis that will follow","to conclude the analysis","to introduce an example"]','"In terms of X" introduces the specific dimension, lens, or angle through which the following point will be examined.','medium'),
  (cid,5,39,'gap_fill','[TOEFL Reading] _____ (with regard to) the study''s internal validity, the random assignment of participants to conditions is a significant strength.','With regard to',NULL,'"With regard to" frames a specific aspect (internal validity) for focused discussion. Formal academic register.','medium'),
  (cid,5,40,'multiple_choice','[TOEFL Listening] The professor uses discourse markers like "now," "turning to," and "so" in a lecture to:','organize the lecture into sections and help listeners track the argument','["add emotional emphasis","express personal opinions","organize the lecture into sections and help listeners track the argument","signal that something is uncertain"]','Spoken lecture discourse markers serve organizational and signposting functions, helping listeners follow the structure.','medium'),

  -- BLOCK 6: TOEFL Academic – Cohesion Devices
  (cid,6,41,'gap_fill','[TOEFL Reading] The experiment was carefully designed. _____ (this approach), the team was able to control for most confounding variables.','Through this approach',NULL,'"Through this approach" = cohesive reference device connecting back to the method described in the previous sentence.','hard'),
  (cid,6,42,'multiple_choice','[TOEFL Reading] "The findings contradict previous assumptions. _____, they open new avenues for research." Which cohesion device is most appropriate?','Moreover','["In conclusion","Moreover","Because","While"]','"Moreover" adds a further, positive consequence of the contradictory findings. Additive cohesion device.','medium'),
  (cid,6,43,'gap_fill','[TOEFL Reading] "Several explanations have been proposed for this phenomenon. _____ (the first of these) suggests that..."','The first of these',NULL,'"The first of these" is a cohesive enumeration marker that organizes multiple points and connects them to the previously introduced set.','medium'),
  (cid,6,44,'multiple_choice','[TOEFL Listening] In the lecture, the professor referred back to the reading passage using the phrase "as mentioned in the reading." This is an example of:','a cohesive reference device that links the lecture to the reading','["a hedging device","a cohesive reference device that links the lecture to the reading","a spoken discourse marker","an exemplification marker"]','"As mentioned in the reading" is an exophoric or intertextual reference device that creates cohesion between texts.','hard'),
  (cid,6,45,'gap_fill','[TOEFL Reading] The data revealed a clear pattern. _____ (such a pattern) suggests that the intervention had a lasting effect on behavior.','Such a pattern',NULL,'"Such a" is a cohesive determiner (demonstrative + intensifier) that refers back to the previously mentioned pattern.','hard'),
  (cid,6,46,'multiple_choice','[TOEFL Reading] "The study identified three key limitations. _____, they were: sample size, duration, and geographic scope." Which marker organizes the list?','Namely','["However","Namely","Therefore","Moreover"]','"Namely" introduces an exhaustive, specific enumeration of the three limitations previously referred to.','medium'),
  (cid,6,47,'gap_fill','[TOEFL Listening] "The professor began by outlining the main argument. _____ (having done so), she then addressed each counterargument in turn."','Having done so',NULL,'"Having done so" = a cohesive participle clause that refers back to the action in the previous clause and advances the sequence.','hard'),
  (cid,6,48,'multiple_choice','[TOEFL Reading] Cohesion in academic texts is achieved through all of the following EXCEPT:','random sentence order','["pronoun reference (it, they, this)","synonymy and lexical chains","discourse markers (however, furthermore)","random sentence order"]','Cohesion is achieved through reference, substitution, conjunction, and lexical chains — not through random ordering.','medium'),

  -- BLOCK 7: TOEFL Academic – Spoken vs Written Discourse Markers
  (cid,7,49,'multiple_choice','[TOEFL Reading] Which of the following would be INAPPROPRIATE in formal academic writing?','You know, the data actually showed something really surprising.','["It is worth noting that the data revealed an unexpected result.","The findings suggest, moreover, a need for further investigation.","As far as methodology is concerned, the study employed a mixed-methods approach.","You know, the data actually showed something really surprising."]','"You know" and "actually" (in its spoken sense) are informal discourse markers inappropriate in formal academic prose.','medium'),
  (cid,7,50,'gap_fill','[TOEFL Listening] "_____ (I mean), what the professor is really arguing is that technology alone cannot solve environmental problems."','I mean',NULL,'"I mean" in spoken discourse is used to clarify or restate what was just said. It is informal and not used in written academic texts.','easy'),
  (cid,7,51,'multiple_choice','[TOEFL Reading] Transform this spoken marker into an appropriate academic written equivalent: "Talking about the results, they were unexpected."','With regard to the results, they proved to be highly unexpected.','["Anyway, the results were unexpected.","Well, the results were unexpected, you know.","With regard to the results, they proved to be highly unexpected.","I mean, the results were really surprising, right?"]','"With regard to the results" replaces the informal "Talking about the results" for academic register.','hard'),
  (cid,7,52,'gap_fill','[TOEFL Reading] In written academic English, "well" at the beginning of a sentence is replaced by markers such as _____.','however / nevertheless / it should be noted',NULL,'Spoken "well" (signaling hesitation, qualification) is replaced in academic writing by formal hedging/contrast markers.','hard'),
  (cid,7,53,'multiple_choice','[TOEFL Listening] The professor opened the lecture with "Well, today we''re going to look at something a bit controversial." What is the function of "Well" here?','to signal a conversational, engaging opening and prepare students for an unusual topic','["to express uncertainty about the topic","to signal a conversational, engaging opening and prepare students for an unusual topic","to conclude the previous lecture","to formally introduce an academic argument"]','"Well" in lecture openings signals an informal, engaging register and hints at something noteworthy to come.','medium'),
  (cid,7,54,'gap_fill','[TOEFL Reading] "In terms of practical implications, _____ (it should be noted) that the findings have been adopted by three national health agencies."','it should be noted',NULL,'"It should be noted that" within a formal frame marker ("In terms of") is characteristic of high-register academic writing.','medium'),
  (cid,7,55,'multiple_choice','[TOEFL Listening] In spoken academic discourse (lectures), which of the following serves as a signposting device telling students what structure the lecture will follow?','Now, I''d like to turn to three factors that explain this phenomenon.','["I mean, there are factors explaining this.","Anyway, let''s get back to the main point.","Now, I''d like to turn to three factors that explain this phenomenon.","You know, this is actually quite complicated."]','"Now, I''d like to turn to three factors" is a spoken signposting marker that previews the structure for the listener.','medium'),
  (cid,7,56,'gap_fill','[TOEFL Reading] _____ (as regards) the policy implications, the authors recommend a phased approach to implementation.','As regards',NULL,'"As regards" is a formal written frame marker. → As regards the policy implications, the authors recommend.','medium'),

  -- BLOCK 8: TOEFL Academic – Mixed Discourse Marker Practice
  (cid,8,57,'multiple_choice','[TOEFL Reading] Select the most appropriate academic written discourse marker: "_____ the ethical concerns raised, the committee approved the study with minor modifications."','Notwithstanding','["Well,","Anyway,","Notwithstanding","You know,"]','"Notwithstanding" is a formal concessive marker (= despite). Appropriate for high-register academic writing.','hard'),
  (cid,8,58,'gap_fill','[TOEFL Reading] _____ (it is noteworthy) that the decline in publication rates coincided precisely with the introduction of the new funding model.','It is noteworthy',NULL,'"It is noteworthy that" draws attention to a significant correlation or observation. Academic stance marker.','medium'),
  (cid,8,59,'multiple_choice','[TOEFL Listening] In a lecture, "So, to sum up what we''ve covered today..." is an example of:','a discourse marker signaling the end of the main content and the beginning of a summary','["a spoken hedging device","a discourse marker signaling the end of the main content and the beginning of a summary","an introduction of a new topic","an expression of uncertainty"]','"So, to sum up" is a closing discourse marker signaling that the lecture is moving to its conclusion/summary.','medium'),
  (cid,8,60,'gap_fill','[TOEFL Reading] _____ (with this in mind), the authors developed a three-stage framework for analyzing the data.','With this in mind',NULL,'"With this in mind" is a cohesive frame marker that links what follows to what was previously established.','hard'),
  (cid,8,61,'multiple_choice','[TOEFL Reading] "On balance, the evidence suggests that urban agriculture offers more benefits than drawbacks." What is the function of "On balance"?','to signal a weighed, overall assessment that considers multiple factors','["to introduce a contrast","to signal a weighed, overall assessment that considers multiple factors","to introduce an example","to express uncertainty"]','"On balance" signals a carefully considered overall judgment — appropriate for balanced academic conclusions.','hard'),
  (cid,8,62,'gap_fill','[TOEFL Listening] "The professor said: ''_____ (turning to) our third and final point — the implications for policy.''"','Turning to',NULL,'"Turning to" signals an organized transition to the final main point. Lecture signposting device.','easy'),
  (cid,8,63,'multiple_choice','[TOEFL Reading] "In this light, it becomes clear that a unilateral approach to climate policy is insufficient." What does "in this light" signal?','a logical consequence or reinterpretation based on the evidence or argument previously presented','["a contrast with a previous point","a logical consequence or reinterpretation based on the evidence or argument previously presented","the introduction of a new topic","an example from a different field"]','"In this light" signals that the following conclusion is derived from the evidence or reasoning previously established.','hard'),
  (cid,8,64,'gap_fill','[TOEFL Reading] _____ (in view of) the growing evidence linking air pollution to dementia, policymakers should prioritize clean air legislation.','In view of',NULL,'"In view of + noun phrase" = in light of / considering. A formal frame marker for justifying a recommendation.','hard'),

  -- BLOCK 9: TOEFL Speaking Tasks
  (cid,9,65,'production','[TOEFL Speaking — 45s] The reading passage presents three arguments in favor of urban farming. The lecture challenges each of these arguments. Summarize the main points of the lecture and explain how they cast doubt on the reading''s claims. Use a variety of written and spoken discourse markers to organize your response. You have 45 seconds to respond.','',NULL,'Spoken markers: "Well, to begin with..." "Now, turning to..." Written markers: "With regard to the first argument..." "It should be noted that..." "Moreover..."','hard'),
  (cid,9,66,'production','[TOEFL Speaking — 45s] In your opinion, what is the most important quality for a university student to develop: critical thinking, time management, or communication skills? Explain your choice and provide specific reasons. Use discourse markers to organize your spoken response clearly. You have 45 seconds.','',NULL,'Spoken discourse structure: "Well, I think..." "I mean, what I''m saying is..." "Anyway, my main point is..." "As far as X is concerned..."','medium'),
  (cid,9,67,'production','[TOEFL Speaking — 45s] Describe the difference between how you communicate in a formal academic setting (e.g., writing a paper or giving a presentation) and how you communicate informally with friends. What markers and strategies do you use differently? You have 45 seconds.','',NULL,'Contrast: informal "Well, you know, I just..." vs formal "With regard to..." "It should be noted..." "Turning to..." "In terms of..."','hard'),

  -- BLOCK 10: TOEFL Writing Tasks
  (cid,10,68,'production','[TOEFL Writing] Write a well-organized essay (150+ words) on the following topic: "The ability to communicate effectively in both formal and informal contexts is one of the most valuable skills a person can develop." Agree or disagree. In your essay, use at least SIX different discourse markers: two from spoken/informal contexts and four from written/academic contexts. Label each one with its function in brackets.','',NULL,'Spoken (if quoted or referred to): [hesitation] "well," [clarification] "I mean." Written: [frame] "with regard to," [stance] "it should be noted," [organization] "turning to," [cohesion] "in this light," [addition] "moreover."','hard'),
  (cid,10,69,'production','[TOEFL Writing] Integrated task: The reading passage discusses three advantages of remote learning. The lecture challenges each claim, using discourse markers like "turning to," "moreover," and "it is worth noting that" to organize the counterarguments. Write a 150+ word response summarizing the lecture''s main points and explaining how they undermine the reading. Use at least FIVE academic discourse markers in your response.','',NULL,'Target markers: "With regard to the first claim..." "It should be noted that..." "Moreover..." "Turning to the second point..." "In view of this evidence..." "On balance, the lecture suggests..."','hard'),
  (cid,10,70,'production','[TOEFL Writing] C2-level task: Write a 200+ word academic essay analyzing the role of discourse markers in effective academic communication. Your essay should: (1) distinguish between spoken and written discourse markers with examples of each, (2) explain the functions of at least four types of academic discourse markers (frame markers, stance markers, cohesion devices, signposting), (3) give specific examples of each type from academic texts or lectures, and (4) use a range of discourse markers within the essay itself to demonstrate your mastery of the subject. This is a reflective, metalinguistic task.','',NULL,'This is a C2 metalinguistic task. Target discourse marker types in the essay: (1) Frame markers: "With regard to...", "As far as X is concerned" (2) Stance markers: "It should be noted that...", "It is worth noting" (3) Cohesion: "Such findings," "In this light," "With this in mind" (4) Signposting: "Turning to," "In the first place," "On balance."','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
